-- Processos da Empresa: manual de procedimentos (como cada atividade deve ser executada).
-- Conteúdo em JSON (título, área, frequência, objetivo, material de apoio, etapas com pontos de controle,
-- entradas, saídas, regras e indicadores). Leitura: todos os usuários (somente versões publicadas).
-- Edição: seção "processos". Alterações ficam em rascunho até serem publicadas (cada publicação gera uma versão).
-- Migração aditiva, com a carga inicial dos 8 processos da apresentação "Mapa de Processos" (agosto/2026).
CREATE TABLE processes (
  id            INTEGER PRIMARY KEY,
  code          TEXT NOT NULL UNIQUE,
  owner_id      INTEGER REFERENCES users(id) ON DELETE SET NULL,   -- responsável por manter o processo atualizado
  status        TEXT NOT NULL DEFAULT 'rascunho' CHECK (status IN ('rascunho', 'publicado', 'arquivado')),
  version       INTEGER NOT NULL DEFAULT 0,                         -- última versão publicada (0 = nunca publicado)
  published     TEXT,                                               -- conteúdo publicado (JSON)
  draft         TEXT,                                               -- alterações em rascunho (JSON)
  published_at  TEXT,
  published_by  INTEGER REFERENCES users(id),
  draft_at      TEXT,
  draft_by      INTEGER REFERENCES users(id),
  created_by    INTEGER REFERENCES users(id),
  created_at    TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at    TEXT NOT NULL DEFAULT (datetime('now'))
);

CREATE TABLE process_versions (
  id            INTEGER PRIMARY KEY,
  process_id    INTEGER NOT NULL REFERENCES processes(id) ON DELETE CASCADE,
  version       INTEGER NOT NULL,
  content       TEXT NOT NULL,
  note          TEXT,
  published_by  INTEGER REFERENCES users(id),
  published_at  TEXT NOT NULL DEFAULT (datetime('now')),
  UNIQUE (process_id, version)
);

-- Documentos e modelos (imagens e PDF) de cada processo
CREATE TABLE process_files (
  id            INTEGER PRIMARY KEY,
  process_id    INTEGER NOT NULL REFERENCES processes(id) ON DELETE CASCADE,
  stored_name   TEXT NOT NULL UNIQUE,
  mime          TEXT NOT NULL,
  size          INTEGER NOT NULL,
  caption       TEXT,
  original_name TEXT,
  uploaded_by   INTEGER NOT NULL REFERENCES users(id),
  created_at    TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE INDEX idx_process_files ON process_files(process_id);

-- Administradores com lista de seções salva recebem a edição de Processos da Empresa
UPDATE users SET sections = json_insert(sections, '$[#]', 'processos')
  WHERE role = 'admin' AND sections IS NOT NULL AND json_valid(sections) AND sections NOT LIKE '%"processos"%';

-- Carga inicial: 8 processos publicados (versão 1)
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (1, 'PRC-01', 'publicado', 1, '{"title": "Relatório Diário de Obra (RDO)", "area": "Obras", "frequency": "Diária", "objective": "Registrar de forma padronizada o que ocorreu na obra a cada dia, com rastreabilidade de mão de obra, equipamentos e ocorrências.", "erp_module": "Aplicativo / Obras → Diário de Obra", "links": [{"kind": "video", "label": "Treinamento App Diário de Obra", "url": "https://www.youtube.com/watch?v=WJRAbubK4SE"}], "inputs": "Efetivo do dia, equipamentos, clima, atividades executadas, ocorrências, materiais recebidos e fotos.", "outputs": "RDO validado e consolidado no sistema; histórico diário da obra.", "rules": null, "indicators": ["% de RDOs preenchidos no prazo", "Nº de ocorrências registradas por mês", "Tempo médio de validação do RDO"], "steps": [{"responsible": "Responsável de Obras", "activity": "Registra o RDO: mão de obra, equipamentos, clima e ocorrências", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Responsável de Obras", "activity": "Anexa fotos e evidências do dia", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Engenheiro de Obra", "activity": "Valida o RDO", "details": null, "control": true, "fail": "Não conforme → retorna para correção", "back_to": 1}, {"responsible": "Mais Controle (ERP)", "activity": "Consolida o RDO da obra", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria", "activity": "Acompanha o avanço via dashboard", "details": null, "control": false, "fail": null, "back_to": null}], "related": [2, 7]}', '2026-08-01 12:00:00');
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (2, 'PRC-02', 'publicado', 1, '{"title": "Medição de Obras", "area": "Engenharia", "frequency": "Mensal/Quinzenal", "objective": "Apurar o avanço físico real da obra e compará-lo ao planejado, sustentando decisões de cronograma e custo.", "erp_module": "Obras → Medição de Obras", "links": [{"kind": "video", "label": "Lançamento Oficial Medição de Obras", "url": "https://www.youtube.com/watch?v=z1YFZB5bB68"}], "inputs": "RDOs do período, projeto executivo, cronograma físico-financeiro.", "outputs": "Medição física aprovada; curva S atualizada.", "rules": null, "indicators": ["Aderência ao cronograma (%)", "Desvio planejado x realizado", "Tempo de aprovação da medição"], "steps": [{"responsible": "Engenheiro de Obra", "activity": "Levanta % executado por serviço em campo", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Mestre de Obras", "activity": "Confere as quantidades executadas", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Mais Controle (ERP)", "activity": "Lançamento da medição no sistema", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Planejamento", "activity": "Compara planejado x realizado (curva S)", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria / Controladoria", "activity": "Aprova a medição", "details": null, "control": true, "fail": "Reprovada → retorna para nova conferência", "back_to": 2}, {"responsible": "Mais Controle (ERP)", "activity": "Atualiza o avanço físico da obra", "details": null, "control": false, "fail": null, "back_to": null}], "related": [1, 3, 7]}', '2026-08-01 12:00:00');
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (3, 'PRC-03', 'publicado', 1, '{"title": "Medição de Contratos", "area": "Engenharia", "frequency": "Mensal/Quinzenal", "objective": "Validar e liberar o pagamento de empreiteiros e fornecedores com base no serviço efetivamente executado e no contrato vigente.", "erp_module": "Obras → Medição de Contratos", "links": [{"kind": "ajuda", "label": "Central de Ajuda: Cadastrar Medição de Contratos", "url": "https://intercom.help/mais_controle/pt/articles/9562697-como-cadastrar-uma-medicao-de-contratos"}], "inputs": "Boletim de medição do contratado, contrato e aditivos, vistoria de campo.", "outputs": "Medição aprovada para pagamento; retenções e descontos calculados.", "rules": null, "indicators": ["Prazo médio de aprovação", "% de glosas por medição", "Valor retido por mês"], "steps": [{"responsible": "Empreiteiro / Fornecedor", "activity": "Apresenta o boletim de medição", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Engenheiro de Obra", "activity": "Vistoria e confere o serviço executado", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Financeiro", "activity": "Verifica saldo contratual e retenções", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria", "activity": "Aprova a medição para pagamento", "details": null, "control": true, "fail": "Reprovada → retorna para nova vistoria", "back_to": 2}, {"responsible": "Financeiro", "activity": "Programa o pagamento ao contratado", "details": null, "control": false, "fail": null, "back_to": null}], "related": [2, 8]}', '2026-08-01 12:00:00');
