INSERT INTO processes (id, code, status, version, published, published_at) VALUES (5, 'PRC-05', 'publicado', 1, '{"title": "Solicitação de Compras", "area": "Suprimentos", "frequency": "Sob demanda", "objective": "Garantir que a aquisição de materiais e serviços siga critérios de necessidade real, orçamento e melhor condição comercial.", "erp_module": "Compras → Solicitações / Cotações / Ordem de Compras", "links": [{"kind": "ajuda", "label": "Central de Ajuda: Cotações e Ordens de Compra", "url": "https://intercom.help/mais_controle/pt/articles/4931066-como-criar-e-gerenciar-cotacoes"}], "inputs": "Necessidade identificada em obra, saldo orçamentário, cotações de fornecedores (mapa de cotação).", "outputs": "Ordem de Compra emitida; material recebido e conferido.", "rules": null, "indicators": ["Prazo médio do pedido à entrega", "Nº de cotações por compra", "% de compras dentro do orçamento"], "steps": [{"responsible": "Obra", "activity": "Identifica a necessidade de material/serviço", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Obra", "activity": "Preenche a Solicitação de Compra (SC) no sistema", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Engenheiro de Obra", "activity": "Aprova a SC (saldo orçamentário)", "details": null, "control": true, "fail": "Reprovada → retorna para ajuste", "back_to": 2}, {"responsible": "Suprimentos", "activity": "Cota com no mínimo 3 fornecedores (serviços: 10 dias · equipamentos: 3 dias · materiais: 2 dias)", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Suprimentos", "activity": "Monta o mapa de cotação comparativo; define o menor preço e a estratégia de negociação", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria / Financeiro", "activity": "Aprova conforme alçada", "details": null, "control": true, "fail": "Reprovada → retorna para nova cotação", "back_to": 4}, {"responsible": "Compras", "activity": "Emite a Ordem de Compra (OC)", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Almoxarife", "activity": "Recebe e confere material x OC", "details": null, "control": false, "fail": null, "back_to": null}], "related": [6]}', '2026-08-01 12:00:00');
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (6, 'PRC-06', 'publicado', 1, '{"title": "Movimentação de Estoque", "area": "Suprimentos", "frequency": "Sob demanda", "objective": "Manter o controle confiável de entradas, saídas e saldo de materiais nos depósitos da obra.", "erp_module": "Estoque → Controle de Estoque / Depósitos", "links": [{"kind": "link", "label": "Ver funcionalidade: Estoque no Mais Controle", "url": "https://maiscontroleerp.com.br/funcionalidades/estoque/"}], "inputs": "Ordem de compra, nota fiscal (XML) do fornecedor, requisições internas da obra.", "outputs": "Saldo de estoque atualizado por depósito; materiais liberados para a obra.", "rules": null, "indicators": ["Acuracidade de estoque (%)", "Nº de rupturas de material (quebra, etc.)", "Tempo médio de atendimento à requisição"], "steps": [{"responsible": "Almoxarife", "activity": "Recebe material e confere NF (XML) x Ordem de Compra", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Mais Controle (ERP)", "activity": "Lança a entrada no estoque", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Obra", "activity": "Solicita retirada via requisição interna", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Almoxarife", "activity": "Confere disponibilidade e libera o material", "details": null, "control": true, "fail": "Indisponível → aciona compras", "back_to": null}, {"responsible": "Mais Controle (ERP)", "activity": "Lança a saída (baixa de estoque ou movimentação entre depósitos)", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Inventário periódico", "activity": "Confere saldo físico x sistema (mensal)", "details": null, "control": true, "fail": "Divergência → ajuste e reconciliação", "back_to": null}], "related": [5]}', '2026-08-01 12:00:00');
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (7, 'PRC-07', 'publicado', 1, '{"title": "Acompanhamento de Obras", "area": "Obras", "frequency": "Semanal/Mensal", "objective": "Monitorar continuamente o desempenho da obra frente ao planejado, antecipando desvios e sustentando decisões corretivas.", "erp_module": "Obras → Cronograma de Gantt / BI → Visão por Obra", "links": [{"kind": "video", "label": "Lançamento do módulo BI", "url": "https://www.youtube.com/watch?v=8QtePhA7EPY"}], "inputs": "RDOs, cronograma físico-financeiro, medições, indicadores de obra.", "outputs": "Plano de ação atualizado; indicadores revisados.", "rules": null, "indicators": ["Índice de desempenho de prazo (SPI)", "Índice de desempenho de custo (CPI)", "Nº de ações corretivas abertas/fechadas"], "steps": [{"responsible": "Mestre de Obras", "activity": "Reporta o avanço diário (RDO)", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Engenheiro", "activity": "Atualiza o cronograma físico-financeiro semanal", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Planejamento", "activity": "Compara planejado x realizado", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Engenharia", "activity": "Identifica desvios e riscos", "details": null, "control": true, "fail": "Desvio crítico → aciona contingência", "back_to": null}, {"responsible": "Engenharia", "activity": "Propõe ações corretivas / replanejamento", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Diretoria", "activity": "Aprova as ações em reunião de acompanhamento", "details": null, "control": true, "fail": "Reprovado → novo replanejamento", "back_to": 5}, {"responsible": "Mais Controle (ERP)", "activity": "Atualiza os indicadores no dashboard da obra", "details": null, "control": false, "fail": null, "back_to": null}], "related": [1, 2]}', '2026-08-01 12:00:00');
INSERT INTO processes (id, code, status, version, published, published_at) VALUES (8, 'PRC-08', 'publicado', 1, '{"title": "Lançamento de Compras e Pagamentos (Pré-lançamento via Zap)", "area": "Financeiro", "frequency": "Sob demanda", "objective": "Agilizar o pré-lançamento de compras/pagamentos via WhatsApp, com dados completos para o financeiro lançar no ERP.", "erp_module": "Financeiro → Lançamentos", "links": [{"kind": "ajuda", "label": "Central de Ajuda: Lançar e controlar Pagamentos", "url": "https://intercom.help/mais_controle/pt/articles/4918347-como-lancar-e-controlar-seus-pagamentos"}], "inputs": null, "outputs": "Lançamento registrado no ERP com centro de custo, etapa e data corretos.", "rules": "Apontar o Centro de Custo; descrever claramente o que foi pago; e informar conta bancária, etapa de apropriação do custo e status do pagamento.", "indicators": ["Tempo médio até o lançamento no ERP", "% de pré-lançamentos completos", "% de divergência de data no lançamento"], "steps": [{"responsible": "Obra", "activity": "Realiza a compra/pagamento (fora do planejamento ou emergencial) e fotografa o comprovante", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Obra", "activity": "Envia o pré-lançamento via WhatsApp (Zap) com centro de custo e descrição", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Obra", "activity": "Informa observação: conta bancária, etapa de apropriação e status do pagamento", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Financeiro", "activity": "Recebe o pré-lançamento via WhatsApp", "details": null, "control": false, "fail": null, "back_to": null}, {"responsible": "Financeiro", "activity": "Confere se as informações estão completas", "details": null, "control": true, "fail": "Incompleto → solicita complementação via WhatsApp", "back_to": 3}, {"responsible": "Financeiro", "activity": "Gera o lançamento no ERP conforme manual do 